"""Synthetic captures for packet-tango.c (generated by idl2wrs from tango.idl).
Usage: mktango.py <outdir>
Writes tango-coverage.pcap(.gz) and tango-coverage-malformed.pcap.

The Tango IDL is mirrored by a small type table; every operation of the five
Device interfaces is sent as a GIOP request and reply, with sample values built
from the types (all AttrValUnion branches, both ClntIdent branches, DevFailed
and MultiDevFailed user exceptions, the readonly attributes)."""
import os
import sys

sys.path.insert(1, os.path.join(os.path.dirname(os.path.abspath(__file__)), '..', 'shared'))















import util as u
from cdr import (
    CDR, giop, iiop_profile, ior, reply_10, reply_12, request_10, request_12, S, sys_exc,
    tc_alias, tc_sequence, tc_string, tk_double, tk_long, tk_void,
)

# ---------------------------------------------------------------- types
Str = ('str',); L = ('long',); UL = ('ulong',); LL = ('ll',); ULL = ('ull',)
SH = ('short',); USH = ('ushort',); B = ('bool',); F = ('float',); D = ('double',); O = ('octet',)
Any = ('any',); Void = None
def E(n): return ('enum', n)
def Q(t): return ('seq', t)
def A(t, n): return ('arr', t, n)
def St(**f): return ('struct', f)
def Un(disc, branches): return ('union', disc, branches)

LockerLanguage = E(2); AttrQuality = E(5); AttrWriteType = E(5); AttrDataFormat = E(4)
DevSource = E(3); ErrSeverity = E(3); DevState = E(14); DispLevel = E(3); PipeWriteType = E(3)
AttributeDataType = E(15)
StrSeq = Q(Str)
TimeVal = St(tv_sec=L, tv_usec=L, tv_nsec=L)
DevCmdInfo = St(cmd_name=Str, cmd_tag=L, in_type=L, out_type=L, in_type_desc=Str, out_type_desc=Str)
DevCmdInfo_2 = St(cmd_name=Str, level=DispLevel, cmd_tag=L, in_type=L, out_type=L,
                  in_type_desc=Str, out_type_desc=Str)
DevError = St(reason=Str, severity=ErrSeverity, desc=Str, origin=Str)
DevErrorList = Q(DevError)
NamedDevError = St(name=Str, index_in_call=L, err_list=DevErrorList)
JavaClntIdent = St(MainClass=Str, uuid=A(ULL, 2))
ClntIdent = Un(LockerLanguage, {0: UL, 1: JavaClntIdent})
AttributeConfig = St(name=Str, writable=AttrWriteType, data_format=AttrDataFormat, data_type=L,
    max_dim_x=L, max_dim_y=L, description=Str, label=Str, unit=Str, standard_unit=Str,
    display_unit=Str, format=Str, min_value=Str, max_value=Str, min_alarm=Str, max_alarm=Str,
    writable_attr_name=Str, extensions=StrSeq)
AttributeConfig_2 = St(name=Str, writable=AttrWriteType, data_format=AttrDataFormat, data_type=L,
    max_dim_x=L, max_dim_y=L, description=Str, label=Str, unit=Str, standard_unit=Str,
    display_unit=Str, format=Str, min_value=Str, max_value=Str, min_alarm=Str, max_alarm=Str,
    writable_attr_name=Str, level=DispLevel, extensions=StrSeq)
AttributeValue = St(value=Any, quality=AttrQuality, time=TimeVal, name=Str, dim_x=L, dim_y=L)
AttributeDim = St(dim_x=L, dim_y=L)
AttributeValue_3 = St(value=Any, quality=AttrQuality, time=TimeVal, name=Str, r_dim=AttributeDim,
                      w_dim=AttributeDim, err_list=DevErrorList)
DevEncoded = St(encoded_format=Str, encoded_data=Q(O))
AttrValUnion = Un(AttributeDataType, {
    0: Q(B), 1: Q(SH), 2: Q(L), 3: Q(LL), 4: Q(F), 5: Q(D), 6: Q(O), 7: Q(USH), 8: Q(UL),
    9: Q(ULL), 10: Q(Str), 11: Q(DevState), 12: DevState, 13: Q(DevEncoded), 14: B})
AttributeValue_4 = St(value=AttrValUnion, quality=AttrQuality, data_format=AttrDataFormat,
    time=TimeVal, name=Str, r_dim=AttributeDim, w_dim=AttributeDim, err_list=DevErrorList)
AttributeValue_5 = St(value=AttrValUnion, quality=AttrQuality, data_format=AttrDataFormat,
    data_type=L, time=TimeVal, name=Str, r_dim=AttributeDim, w_dim=AttributeDim, err_list=DevErrorList)
ChangeEventProp = St(rel_change=Str, abs_change=Str, extensions=StrSeq)
PeriodicEventProp = St(period=Str, extensions=StrSeq)
ArchiveEventProp = St(rel_change=Str, abs_change=Str, period=Str, extensions=StrSeq)
EventProperties = St(ch_event=ChangeEventProp, per_event=PeriodicEventProp, arch_event=ArchiveEventProp)
AttributeAlarm = St(min_alarm=Str, max_alarm=Str, min_warning=Str, max_warning=Str, delta_t=Str,
                    delta_val=Str, extensions=StrSeq)
AttributeConfig_3 = St(name=Str, writable=AttrWriteType, data_format=AttrDataFormat, data_type=L,
    max_dim_x=L, max_dim_y=L, description=Str, label=Str, unit=Str, standard_unit=Str,
    display_unit=Str, format=Str, min_value=Str, max_value=Str, writable_attr_name=Str,
    level=DispLevel, att_alarm=AttributeAlarm, event_prop=EventProperties, extensions=StrSeq,
    sys_extensions=StrSeq)
AttributeConfig_5 = St(name=Str, writable=AttrWriteType, data_format=AttrDataFormat, data_type=L,
    memorized=B, mem_init=B, max_dim_x=L, max_dim_y=L, description=Str, label=Str, unit=Str,
    standard_unit=Str, display_unit=Str, format=Str, min_value=Str, max_value=Str,
    writable_attr_name=Str, level=DispLevel, root_attr_name=Str, enum_labels=StrSeq,
    att_alarm=AttributeAlarm, event_prop=EventProperties, extensions=StrSeq, sys_extensions=StrSeq)
PipeConfig = St(name=Str, description=Str, label=Str, level=DispLevel, writable=PipeWriteType,
                extensions=StrSeq)
# DevPipeDataElt is a forward-declared, recursive struct; the generated code
# cannot decode the sequence, so the sample always has zero elements.
DevPipeBlob = St(name=Str, blob_data=Q(('fwd',)))
DevPipeData = St(name=Str, time=TimeVal, data_blob=DevPipeBlob)
DevInfo = St(dev_class=Str, server_id=Str, server_host=Str, server_version=L, doc_url=Str)
DevInfo_3 = St(dev_class=Str, server_id=Str, server_host=Str, server_version=L, doc_url=Str, dev_type=Str)
DevCmdHistory = St(time=TimeVal, cmd_failed=B, value=Any, errors=DevErrorList)
DevAttrHistory = St(attr_failed=B, value=AttributeValue, errors=DevErrorList)
DevAttrHistory_3 = St(attr_failed=B, value=AttributeValue_3)
EltInArray = St(start=L, nb_elt=L)
DevAttrHistory_4 = St(name=Str, dates=Q(TimeVal), value=Any, quals=Q(AttrQuality),
    quals_array=Q(EltInArray), r_dims=Q(AttributeDim), r_dims_array=Q(EltInArray),
    w_dims=Q(AttributeDim), w_dims_array=Q(EltInArray), errors=Q(DevErrorList),
    errors_array=Q(EltInArray))
DevAttrHistory_5 = St(name=Str, data_format=AttrDataFormat, data_type=L, dates=Q(TimeVal),
    value=Any, quals=Q(AttrQuality), quals_array=Q(EltInArray), r_dims=Q(AttributeDim),
    r_dims_array=Q(EltInArray), w_dims=Q(AttributeDim), w_dims_array=Q(EltInArray),
    errors=Q(DevErrorList), errors_array=Q(EltInArray))
DevCmdHistory_4 = St(dates=Q(TimeVal), value=Any, dims=Q(AttributeDim), dims_array=Q(EltInArray),
    errors=Q(DevErrorList), errors_array=Q(EltInArray), cmd_type=L)
DevFailed = St(errors=DevErrorList)
MultiDevFailed = St(errors=Q(NamedDevError))

# interface: operation -> (in types, return type)
OPS = {
 'Device': {
  'command_inout': ([Str, Any], Any),
  'get_attribute_config': ([StrSeq], Q(AttributeConfig)),
  'set_attribute_config': ([Q(AttributeConfig)], Void),
  'read_attributes': ([StrSeq], Q(AttributeValue)),
  'write_attributes': ([Q(AttributeValue)], Void),
  'ping': ([], Void),
  'black_box': ([L], StrSeq),
  'info': ([], DevInfo),
  'command_list_query': ([], Q(DevCmdInfo)),
  'command_query': ([Str], DevCmdInfo)},
 'Device_2': {
  'command_inout_2': ([Str, Any, DevSource], Any),
  'read_attributes_2': ([StrSeq, DevSource], Q(AttributeValue)),
  'get_attribute_config_2': ([StrSeq], Q(AttributeConfig_2)),
  'command_list_query_2': ([], Q(DevCmdInfo_2)),
  'command_query_2': ([Str], DevCmdInfo_2),
  'command_inout_history_2': ([Str, L], Q(DevCmdHistory)),
  'read_attribute_history_2': ([Str, L], Q(DevAttrHistory))},
 'Device_3': {
  'read_attributes_3': ([StrSeq, DevSource], Q(AttributeValue_3)),
  'write_attributes_3': ([Q(AttributeValue)], Void),
  'read_attribute_history_3': ([Str, L], Q(DevAttrHistory_3)),
  'info_3': ([], DevInfo_3),
  'get_attribute_config_3': ([StrSeq], Q(AttributeConfig_3)),
  'set_attribute_config_3': ([Q(AttributeConfig_3)], Void)},
 'Device_4': {
  'read_attribute_history_4': ([Str, L], DevAttrHistory_4),
  'command_inout_history_4': ([Str, L], DevCmdHistory_4),
  'command_inout_4': ([Str, Any, DevSource, ClntIdent], Any),
  'read_attributes_4': ([StrSeq, DevSource, ClntIdent], Q(AttributeValue_4)),
  'write_attributes_4': ([Q(AttributeValue_4), ClntIdent], Void),
  'set_attribute_config_4': ([Q(AttributeConfig_3), ClntIdent], Void),
  'write_read_attributes_4': ([Q(AttributeValue_4), ClntIdent], Q(AttributeValue_4))},
 'Device_5': {
  'get_attribute_config_5': ([StrSeq], Q(AttributeConfig_5)),
  'set_attribute_config_5': ([Q(AttributeConfig_5), ClntIdent], Void),
  'read_attributes_5': ([StrSeq, DevSource, ClntIdent], Q(AttributeValue_5)),
  'write_read_attributes_5': ([Q(AttributeValue_4), StrSeq, ClntIdent], Q(AttributeValue_5)),
  'read_attribute_history_5': ([Str, L], DevAttrHistory_5),
  'get_pipe_config_5': ([StrSeq], Q(PipeConfig)),
  'set_pipe_config_5': ([Q(PipeConfig), ClntIdent], Void),
  'read_pipe_5': ([Str, ClntIdent], DevPipeData),
  'write_pipe_5': ([DevPipeData, ClntIdent], Void),
  'write_read_pipe_5': ([DevPipeData, ClntIdent], DevPipeData)},
}
ATTRS = {'_get_name': Str, '_get_description': Str, '_get_state': DevState,
         '_get_status': Str, '_get_adm_name': Str}

# ---------------------------------------------------------------- sample values
class Gen:
    def __init__(self): self.n = 0
    def num(self):
        self.n += 1
        return self.n
    def any(self):
        k = self.num() % 6
        if k == 0:
            return any_of(S(tk_long), lambda c: c.long(self.num()))
        if k == 1:
            return any_of(lambda c: tc_alias(c, lambda e: tc_sequence(e, S(tk_long), 0), 'IDL:Tango/DevVarLongArray:1.0', 'DevVarLongArray'),
                          lambda c: (c.ulong(3), c.long(1), c.long(2), c.long(3)))
        if k == 2:
            return any_of(lambda c: tc_string(c, 0), lambda c: c.string('any string'))
        if k == 3:
            return any_of(S(tk_double), lambda c: c.double(12.5))
        if k == 4:
            return any_of(lambda c: tc_alias(c, lambda e: tc_sequence(e, lambda x: tc_string(x, 0), 0), 'IDL:Tango/DevVarStringArray:1.0', 'DevVarStringArray'),
                          lambda c: (c.ulong(2), c.string('a'), c.string('bc')))
        return any_of(S(tk_void))
    def sample(self, T, n=2, label=None):
        k = T[0]
        if k == 'str': return 'str%d' % self.num()
        if k in ('long', 'short'): return self.num() - 20
        if k in ('ulong', 'ushort', 'ull', 'octet'): return self.num()
        if k == 'll': return -self.num() * 100000000000
        if k == 'bool': return self.num() % 2 == 0
        if k in ('float', 'double'): return self.num() + 0.5
        if k == 'enum': return self.num() % T[1]
        if k == 'any': return self.any()
        if k == 'fwd': return None
        if k == 'seq':
            if T[1] == ('fwd',): return []
            return [self.sample(T[1], n) for _ in range(n)]
        if k == 'arr': return [self.sample(T[1]) for _ in range(T[2])]
        if k == 'struct': return {name: self.sample(t, n) for name, t in T[1].items()}
        if k == 'union':
            lab = label if label is not None else self.num() % len(T[2])
            return (lab, self.sample(T[2][lab], n))
        raise ValueError(k)

def enc(c, T, v):
    k = T[0]
    if k == 'str': c.string(v)
    elif k == 'long': c.long(v)
    elif k == 'short': c.short(v)
    elif k == 'ulong': c.ulong(v)
    elif k == 'ushort': c.ushort(v)
    elif k == 'll': c.longlong(v)
    elif k == 'ull': c.ulonglong(v)
    elif k == 'bool': c.boolean(v)
    elif k == 'float': c.float(v)
    elif k == 'double': c.double(v)
    elif k == 'octet': c.octet(v)
    elif k == 'enum': c.ulong(v)
    elif k == 'any': v(c)
    elif k == 'seq':
        c.ulong(len(v))
        for x in v: enc(c, T[1], x)
    elif k == 'arr':
        for x in v: enc(c, T[1], x)
    elif k == 'struct':
        for name, t in T[1].items(): enc(c, t, v[name])
    elif k == 'union':
        c.ulong(v[0]); enc(c, T[2][v[0]], v[1])
    else: raise ValueError(k)

def any_of(tcfn, datafn=None):
    def f(c):
        tcfn(c)
        if datafn: datafn(c)
    return f

# ---------------------------------------------------------------- messages
def args_fn(g, ins, over=None):
    vals = over if over is not None else [g.sample(t) for t in ins]
    def f(c):
        for t, v in zip(ins, vals): enc(c, t, v)
    return f

def req(minor, le, rid, key, op, argsf, ctx=None):
    if minor == 2:
        return giop(2, 0, request_12(rid, ('key', key), op, argsf, le, ctx).bytes(), le)
    return giop(minor, 0, request_10(rid, key, op, minor=minor, le=le, ctx=ctx, args_fn=argsf).bytes(), le)

def rep(minor, le, rid, status, bodyf):
    if minor == 2:
        return giop(2, 1, reply_12(rid, status, bodyf, le).bytes(), le)
    return giop(minor, 1, reply_10(rid, status, bodyf, le).bytes(), le)

def ret_fn(g, rt, v=None):
    if rt is None: return None
    val = g.sample(rt) if v is None else v
    return lambda c: enc(c, rt, val)

def exc_fn(name, T, g, v=None):
    val = g.sample(T) if v is None else v
    def f(c):
        c.string('IDL:Tango/%s:1.0' % name)
        enc(c, T, val)
    return f

class Flow:
    """Requests and replies for one TCP connection"""
    def __init__(self, conn, g, rid=1):
        self.conn = conn; self.g = g; self.rid = rid
    def call(self, key, op, ins, rt, minor=2, le=False, status=0, bodyf='auto', over=None, seg=None, ctx=None):
        self.rid += 1
        rid = self.rid
        m = req(minor, le, rid, key, op, args_fn(self.g, ins, over), ctx)
        self.conn.send(m) if seg is None else self.conn.csegs(m, seg)
        if bodyf == 'auto':
            bodyf = ret_fn(self.g, rt)
        self.conn.recv(rep(minor, le, rid, status, bodyf))
        return rid

def locate_forward(rid, repoid, key, minor=2):
    c = CDR(12)
    c.ulong(rid).ulong(2)    # OBJECT_FORWARD
    c.align(8)
    ior(c, repoid, [(0, iiop_profile('tango.example.test', 10000, key, 0))])
    return giop(minor, 4, c.bytes())

def locate_req(rid, key):
    return giop(2, 3, CDR(12).ulong(rid).ushort(0).seq(key).bytes())

def main_frames():
    o = []
    g = Gen()
    # ===== A: TCP, GIOP 1.2, big endian, no IOR known: heuristic dissector =====
    A = u.Conn(o, 40000, 2809)
    fa = Flow(A, g)
    for iface, ops in OPS.items():
        for op, (ins, rt) in ops.items():
            fa.call(b'tango/dev', op, ins, rt)
    for op, rt in ATTRS.items():
        fa.call(b'tango/dev', op, [], rt)
    # every AttrValUnion branch in one list, as write_attributes_4 / reply of read_attributes_5
    def allunion(T):
        return [g.sample(T, 1) for _ in range(15)]
    def av(T, lab):
        s = g.sample(T); s['value'] = g.sample(AttrValUnion, 3, label=lab); return s
    for T, op, ins, rt in ((AttributeValue_4, 'write_attributes_4', [Q(AttributeValue_4), ClntIdent], Void),
                           (AttributeValue_5, 'read_attributes_5', [StrSeq, DevSource, ClntIdent], Q(AttributeValue_5))):
        vals = [av(T, lab) for lab in range(15)]
        if op == 'write_attributes_4':
            fa.call(b'tango/dev', op, ins, rt, over=[vals, (0, 77)])
        else:
            fa.call(b'tango/dev', op, ins, rt, bodyf=lambda c, vals=vals: enc(c, Q(AttributeValue_5), vals))
    # ClntIdent JAVA branch
    fa.call(b'tango/dev', 'command_inout_4', OPS['Device_4']['command_inout_4'][0], Any,
            over=['Status', g.any(), 1, (1, {'MainClass': 'org.tango.Client', 'uuid': [0x1122334455667788, 0x99aabbccddeeff00]})])
    # empty sequences
    fa.call(b'tango/dev', 'read_attributes_4', [StrSeq, DevSource, ClntIdent], Q(AttributeValue_4),
            over=[[], 0, (0, 1)], bodyf=lambda c: enc(c, Q(AttributeValue_4), []))
    fa.call(b'tango/dev', 'get_attribute_config_5', [StrSeq], Q(AttributeConfig_5),
            over=[[]], bodyf=lambda c: enc(c, Q(AttributeConfig_5), []))
    # user exceptions
    ops_exc = [('command_inout_4', 'DevFailed', DevFailed), ('read_attributes_5', 'DevFailed', DevFailed),
               ('write_attributes_4', 'MultiDevFailed', MultiDevFailed), ('write_read_attributes_5', 'MultiDevFailed', MultiDevFailed),
               ('ping', 'DevFailed', DevFailed), ('_get_state', 'DevFailed', DevFailed)]
    for op, name, T in ops_exc:
        ins = OPS['Device_5'].get(op) or OPS['Device_4'].get(op) or OPS['Device'].get(op) or ([], None)
        fa.call(b'tango/dev', op, ins[0], None, status=1, bodyf=exc_fn(name, T, g))
    # a user exception the dissector does not know, a system exception, location forward
    fa.call(b'tango/dev', 'ping', [], None, status=1, bodyf=lambda c: (c.string('IDL:Other/Unknown:1.0'), c.ulong(3)))
    fa.call(b'tango/dev', 'ping', [], None, status=2, bodyf=lambda c: sys_exc(c))
    fa.call(b'tango/dev', 'read_pipe_5', [Str, ClntIdent], None, status=2, bodyf=lambda c: sys_exc(c))
    fa.call(b'tango/dev', 'command_inout', [Str, Any], None, status=2, bodyf=lambda c: sys_exc(c))
    # location forward and other reply statuses with an IOR (handled by GIOP, not by Tango)
    for st in (3, 4, 5, 9):
        fa.call(b'tango/dev', 'ping', [], None, status=st,
                bodyf=lambda c: ior(c, 'IDL:Tango/Device_5:1.0', [(0, iiop_profile('fwd.example.test', 10001, b'fwdkey', 0))]))
    # an operation unknown to Tango
    fa.call(b'tango/dev', 'read_attributes_5', [StrSeq, DevSource, ClntIdent], Q(AttributeValue_5))
    fa.call(b'tango/dev', 'not_a_tango_op', [Str], None, bodyf=None)
    fa.call(b'tango/dev', 'ping', [], None)
    A.fin()

    # ===== B: the object keys learned from IORs: explicit dissectors per interface =====
    B = u.Conn(o, 40001, 2810, cisn=7000, sisn=9000)
    fb = Flow(B, g, 100)
    for i, iface in enumerate(OPS):
        key = ('devkey-%d' % i).encode()
        rid = fb.rid + 1; fb.rid += 1
        B.send(locate_req(rid, key))
        B.recv(locate_forward(rid, 'IDL:Tango/%s:1.0' % iface, key))
        for op, (ins, rt) in OPS[iface].items():
            fb.call(key, op, ins, rt)
    # explicit dissector but an operation of another interface (not matched by the module)
    fb.call(b'devkey-4', 'ping', [], None)
    fb.call(b'devkey-0', 'read_pipe_5', [Str, ClntIdent], DevPipeData)
    fb.call(b'devkey-4', '_get_name', [], Str)
    fb.call(b'devkey-4', 'read_attributes_5', [StrSeq, DevSource, ClntIdent], None, status=1,
            bodyf=exc_fn('DevFailed', DevFailed, g))
    fb.call(b'devkey-1', 'read_attributes_5', [StrSeq, DevSource, ClntIdent], None, status=2,
            bodyf=lambda c: sys_exc(c))
    B.fin()

    # ===== C: UDP (DIOP) and the other GIOP versions / byte orders =====
    rid = 500
    for minor, le in ((2, True), (1, False), (1, True), (0, False), (0, True)):
        for op, iface in (('read_attributes_5', 'Device_5'), ('write_read_attributes_5', 'Device_5'),
                          ('command_inout_4', 'Device_4'), ('read_attribute_history_4', 'Device_4'),
                          ('get_attribute_config_3', 'Device_3'), ('read_attribute_history_2', 'Device_2'),
                          ('command_list_query', 'Device'), ('write_pipe_5', 'Device_5'),
                          ('get_pipe_config_5', 'Device_5')):
            ins, rt = OPS[iface][op]
            rid += 1
            sp = 41000 + minor * 10 + int(le)
            o.append(u.udp(sp, 41100, req(minor, le, rid, b'udpkey', op, args_fn(g, ins))))
            o.append(u.udp(41100, sp, rep(minor, le, rid, 0, ret_fn(g, rt)), src='192.0.2.2', dst='192.0.2.1'))
    # UDP user exceptions and attribute replies
    for minor, le in ((2, False), (2, True), (0, False)):
        rid += 1
        o.append(u.udp(41200, 41100, req(minor, le, rid, b'udpkey', 'read_attributes_4', args_fn(g, [StrSeq, DevSource, ClntIdent]))))
        o.append(u.udp(41100, 41200, rep(minor, le, rid, 1, exc_fn('DevFailed', DevFailed, g)), src='192.0.2.2', dst='192.0.2.1'))
        rid += 1
        o.append(u.udp(41200, 41100, req(minor, le, rid, b'udpkey', '_get_status', lambda c: None)))
        o.append(u.udp(41100, 41200, rep(minor, le, rid, 0, lambda c: c.string('device is on')), src='192.0.2.2', dst='192.0.2.1'))
        rid += 1
        o.append(u.udp(41200, 41100, req(minor, le, rid, b'udpkey', 'write_attributes_3', args_fn(g, [Q(AttributeValue)]))))
        o.append(u.udp(41100, 41200, rep(minor, le, rid, 1, exc_fn('MultiDevFailed', MultiDevFailed, g)), src='192.0.2.2', dst='192.0.2.1'))
    # Reproducer of "idl2wrs: Do not generate a loop for sequences of forward
    # declarations": write_pipe_5 whose DevPipeBlob.blob_data claims 0xffffffff
    # elements of the forward-declared DevPipeDataElt. The generated code
    # reads the count and stops, the ClntIdent after it is decoded.
    o.append(u.udp(41300, 41101, fwd_seq(0xffffffff)))
    o.append(u.udp(41300, 41101, fwd_seq(0)))
    return o


def fwd_seq(count):
    rh = CDR(12)
    rh.ulong(0).ulong(1).octet(1).raw(b'\0\0\0').seq(b'key1').string('write_pipe_5').seq(b'')
    rh.string('pipe').long(1).long(2).long(3).string('blob').ulong(count)
    rh.ulong(0).long(1234)
    return giop(0, 0, rh.bytes())


def malformed_frames():
    o = []
    g = Gen()
    # truncated Tango requests and replies of every kind
    def udp(sp, data): o.append(u.udp(sp, 41500, data))
    rid = 900
    for minor in (2, 0):
        for op, iface in (('read_attributes_5', 'Device_5'), ('write_read_attributes_5', 'Device_5'),
                          ('write_pipe_5', 'Device_5'), ('get_attribute_config_5', 'Device_5'),
                          ('command_inout_4', 'Device_4'), ('read_attribute_history_5', 'Device_5')):
            ins, rt = OPS[iface][op]
            full = req(minor, False, rid + 1, b'mal', op, args_fn(g, ins))
            for cut in (len(full) - 3, 60, 70, 40):
                rid += 1
                body = full[12:cut] if cut < len(full) else full[12:]
                o.append(u.udp(41400 + minor, 41500, giop(minor, 0, body)))
            full = rep(minor, False, rid, 0, ret_fn(g, rt))
            for cut in (len(full) - 5, 30, 60):
                o.append(u.udp(41500, 41400 + minor, giop(minor, 1, full[12:cut]), src='192.0.2.2', dst='192.0.2.1'))
    # sequence length larger than the data left
    for op, ins in (('read_attributes_5', [StrSeq, DevSource, ClntIdent]), ('write_attributes_4', [Q(AttributeValue_4), ClntIdent]),
                    ('get_pipe_config_5', [StrSeq])):
        rid += 1
        def f(c):
            c.ulong(0x7fffffff)
        o.append(u.udp(41410, 41500, req(2, False, rid, b'mal', op, f)))
    # an any whose TypeCode is cut short, unknown union label
    rid += 1
    o.append(u.udp(41411, 41500, req(2, False, rid, b'mal', 'command_inout_4', lambda c: (c.string('x'), c.ulong(14)))))
    rid += 1
    o.append(u.udp(41411, 41500, req(2, False, rid, b'mal', 'write_attributes_4',
        lambda c: (c.ulong(1), c.ulong(99), c.ulong(1)))))
    # forward-declared sequence with elements: the elements' bytes are not skipped
    rid += 1
    rh = CDR(12)
    rh.ulong(0).ulong(rid).octet(1).raw(b'\0\0\0').seq(b'key1').string('write_pipe_5').seq(b'')
    rh.string('pipe').long(1).long(2).long(3).string('blob').ulong(2)
    rh.string('elt1').ulong(2).ulong(0).ulong(0).string('inner').string('elt2')
    o.append(u.udp(41412, 41500, giop(0, 0, rh.bytes())))
    # user exception reply without a body (GIOP raises the exception)
    o.append(u.udp(41413, 41500, req(2, False, 990, b'mal', 'ping', None)))
    o.append(u.udp(41500, 41413, rep(2, False, 990, 1, None), src='192.0.2.2', dst='192.0.2.1'))
    return o


def main():
    out = sys.argv[1] if len(sys.argv) > 1 else '.'
    os.makedirs(out, exist_ok=True)
    f = main_frames()
    u.write_pcap(os.path.join(out, 'tango-coverage.pcap'), f)
    u.gz(os.path.join(out, 'tango-coverage.pcap'))
    import shutil
    shutil.copy(os.path.join(out, 'tango-coverage.pcap.gz'), os.path.join(out, 'tango_coverage.pcap.gz'))
    m = malformed_frames()
    u.write_pcap(os.path.join(out, 'tango-coverage-malformed.pcap'), m)
    print('%d frames, %d malformed-capture frames' % (len(f), len(m)))

if __name__ == '__main__':
    main()
